SELECT gen_random_uuid()::text, 'formula', '$L$', 'Arc Length in Polar Coordinates', '$L = \int_\alpha^\beta\sqrt{r^2 + \left(\frac{dr}{d\theta}\right)^2}\,d\theta$', NULL, 'The length of a polar curve.', '[{"symbol":"$r = f(\\theta)$","meaning":"the curve"},{"symbol":"$\\alpha, \\beta$","meaning":"the angles"}]'::jsonb, 'The cardioid $r = a(1 + \cos\theta)$ has length $8a$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Calculus 2' AND t."subject" = 'Mathematics' AND s."normKey" = 'arc length and surface area' AND s."active"), 'Arc length', true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Calculus 2' AND t."subject" = 'Mathematics'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
