SELECT gen_random_uuid()::text, 'formula', '$\bar x = \frac{\int x\,dA}{A}$', 'Centroid of a Plane Area', '$\bar x = \frac{1}{A}\int_a^b x f(x)\,dx,\qquad \bar y = \frac{1}{2A}\int_a^b\left[f(x)\right]^2dx$', NULL, 'The balance point of the region under a curve.', '[{"symbol":"$f(x)$","meaning":"the curve above the $x$-axis on $[a, b]$"},{"symbol":"$A$","meaning":"the area"}]'::jsonb, 'For a region between two curves: x̄ = (1/A)∫x(f − g)dx and ȳ = (1/2A)∫(f² − g²)dx.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Calculus 2' AND t."subject" = 'Mathematics' AND s."normKey" = 'centroids and moments of inertia' AND s."active"), 'Centroids', true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Calculus 2' AND t."subject" = 'Mathematics'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
