SELECT gen_random_uuid()::text, 'formula', '$\frac{bh^3}{12}$', 'Moments of Inertia of Common Areas', '$\text{rectangle: } \bar I = \tfrac{bh^3}{12},\ I_{\text{base}} = \tfrac{bh^3}{3};\quad \text{triangle: } \bar I = \tfrac{bh^3}{36},\ I_{\text{base}} = \tfrac{bh^3}{12};\quad \text{circle: } \bar I = \tfrac{\pi r^4}{4}$', NULL, 'The second moments of area used in beam and gate problems.', '[{"symbol":"$b, h$","meaning":"base and height"},{"symbol":"$r$","meaning":"radius"},{"symbol":"$\\bar I$","meaning":"about the centroidal axis parallel to the base"}]'::jsonb, 'The polar moment of a circle is twice: $\frac{\pi r^4}{2}$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Calculus 2' AND t."subject" = 'Mathematics' AND s."normKey" = 'centroids and moments of inertia' AND s."active"), 'Moments of inertia', true, 'PENDING', now(), now()
