SELECT gen_random_uuid()::text, 'formula', '$I = \bar I + Ad^2$', 'Parallel Axis Theorem', '$I = \bar I + Ad^2,\qquad k = \sqrt{\frac{I}{A}}$', NULL, 'Moving a moment of inertia to a parallel axis, and the radius of gyration.', '[{"symbol":"$\\bar I$","meaning":"moment about the centroidal axis"},{"symbol":"$A$","meaning":"area"},{"symbol":"$d$","meaning":"distance between the axes"},{"symbol":"$k$","meaning":"radius of gyration"}]'::jsonb, 'Always add Ad², from the centroidal axis only; never subtract.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Calculus 2' AND t."subject" = 'Mathematics' AND s."normKey" = 'centroids and moments of inertia' AND s."active"), 'Moments of inertia', true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Calculus 2' AND t."subject" = 'Mathematics'
